<?php $this->layout('default'); use Moves\Services\PlatformDirectory as D; use Moves\Support\CmsView as V;
$filters = ['q' => V::queryString('q'), 'status' => V::queryString('status')]; $result = D::companies($filters, V::queryPage()); $st = ['active' => 'Ativa', 'inactive' => 'Inativa']; ?>
<div class="cms-card"><form class="cms-filters" method="get"><?= V::field('Pesquisar', 'q', $filters['q'], ['type' => 'search']) ?><?= V::field('Situação', 'status', $filters['status'], ['type' => 'select', 'choices' => ['' => 'Todas'] + $st]) ?><button class="cms-btn">Filtrar</button></form>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhuma empresa encontrada.') ?><?php else: ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Empresas"><table><thead><tr><th>Empresa</th><th>Responsável</th><th class="num">Membros</th><th>Plano</th><th>Situação</th></tr></thead><tbody><?php foreach ($result['rows'] as $c): ?><tr><td><a href="/empresas/<?= (int) $c['id'] ?>"><?= V::e($c['trade_name'] ?: $c['name']) ?></a></td><td><?= V::e($c['owner_email']) ?></td><td class="num"><?= (int) $c['members_count'] ?></td><td><?= V::e($c['plan_name'] ?? '—') ?></td><td><?= V::badge($c['status'], $st[$c['status']] ?? $c['status']) ?></td></tr><?php endforeach; ?></tbody></table></div><?= V::pager($result) ?><?php endif; ?></div>
